begin;
select no_plan();
\ir helpers/polat_experiment_fixtures.sql
select pg_temp.bridge_setup(8001);select pg_temp.bridge_setup(8002);select pg_temp.bridge_setup(8003,1,'0.02',1);select pg_temp.bridge_setup(8004,3,'0.02');select pg_temp.bridge_setup(8005);select pg_temp.bridge_setup(8006);
select is((select count(*)from private.polat_experiment_runs where tenant_id=pg_temp.bridge_id(8001,'1000')),1::bigint,'run prepared once in private store');
select is((private.polat_experiment_prepare_fixture(pg_temp.bridge_id(8001,'1000'),pg_temp.bridge_id(9999,'2000'),(select b::text from polat_experiment_cases where n=8001))->>'run_id'),pg_temp.bridge_id(8001,'2000')::text,'new process/run UUID returns original authorization scope');
select is((select count(*)from private.polat_experiment_runs where tenant_id=pg_temp.bridge_id(8001,'1000')),1::bigint,'new directory cannot create another budget');
select throws_ok($q$select private.polat_experiment_prepare_fixture(pg_temp.bridge_id(8002,'1000'),pg_temp.bridge_id(9998,'2000'),(select b::text from polat_experiment_cases where n=8001))$q$,'42501','POLAT_EXPERIMENT_UNAVAILABLE','authorization/account scope cannot move across tenants');
select throws_ok($q$select private.polat_experiment_prepare_fixture(pg_temp.bridge_id(8001,'1000'),pg_temp.bridge_id(9999,'2000'),jsonb_set((select b from polat_experiment_cases where n=8001),'{currency}','"EUR"')::text)$q$,'42501','POLAT_EXPERIMENT_UNAVAILABLE','same approval cannot change currency');
select throws_ok($q$select private.polat_experiment_prepare_fixture(pg_temp.bridge_id(8001,'1000'),pg_temp.bridge_id(9999,'2000'),replace((select b::text from polat_experiment_cases where n=8001),'{','{"version":1,')::text)$q$,'22023','FSE_INVALID','duplicate JSON keys rejected before JSONB');
select throws_ok($q$select private.polat_experiment_prepare_fixture(pg_temp.bridge_id(8001,'1000'),pg_temp.bridge_id(9999,'2000'),jsonb_set((select b from polat_experiment_cases where n=8001),'{maximum_spend}','0.02')::text)$q$,'22023','POLAT_EXPERIMENT_INVALID','numeric JSON is not monetary authority');
select throws_ok($q$select private.polat_experiment_decimal('0.0000000000000000001')$q$,'22023','POLAT_EXPERIMENT_INVALID','no 19th decimal rounding');
select throws_ok($q$select private.polat_experiment_decimal('1e-2')$q$,'22023','POLAT_EXPERIMENT_INVALID','no exponent monetary notation');
select is(private.polat_experiment_decimal('0.000000000000000001'),0.000000000000000001::numeric,'exact smallest atomic decimal');
select is(private.polat_experiment_decimal('999999999999999999999999999999'),999999999999999999999999999999::numeric,'exact thirty digit boundary');
select throws_ok($q$select private.polat_experiment_decimal('1000000000000000000000000000000')$q$,'22023','POLAT_EXPERIMENT_INVALID','thirty-one digits rejected');

select is(pg_temp.bridge_reserve(8001)->>'replay','false','first attempt reserved atomically');
select is(pg_temp.bridge_reserve(8001)->>'replay','true','same logical target replay is not another request');
select is((select request_count from private.polat_experiment_runs where id=pg_temp.bridge_id(8001,'2000')),1,'replay count remains one');
select is((select reserved_liability from private.polat_experiment_runs where id=pg_temp.bridge_id(8001,'2000')),0.02::numeric,'exact liability persists');
select throws_ok($q$select private.polat_experiment_reserve_fixture(pg_temp.bridge_id(8001,'1000'),pg_temp.bridge_id(8001,'2000'),pg_temp.bridge_id(1,'3000'),repeat('e',64),repeat('e',64),repeat('f',64),repeat('a',64))$q$,'40001','POLAT_EXPERIMENT_BINDING_CHANGED','binding/model/corpus drift denied before dispatch');
select throws_ok($q$select private.polat_experiment_reserve_fixture(pg_temp.bridge_id(8002,'1000'),pg_temp.bridge_id(8001,'2000'),pg_temp.bridge_id(1,'3000'),repeat('e',64),repeat('e',64),repeat('f',64),repeat('a',64))$q$,'42501','POLAT_EXPERIMENT_UNAVAILABLE','foreign run has uniform not-available result');
select is(pg_temp.bridge_begin(8001)->>'dispatch','true','one committed dispatch marker');
select is(pg_temp.bridge_begin(8001)->>'dispatch','false','duplicate begin never issues another send permission');
select is((select count(*)from private.polat_experiment_evidence where run_id=pg_temp.bridge_id(8001,'2000')and stage='DISPATCH_STARTED'),1::bigint,'one immutable start');
select throws_ok($q$select private.polat_experiment_record_fixture(pg_temp.bridge_id(8001,'1000'),pg_temp.bridge_id(8001,'2000'),pg_temp.bridge_id(800101,'3000'),(select binding_hash from private.polat_experiment_runs where id=pg_temp.bridge_id(8001,'2000')),pg_temp.bridge_id(1,'4000'),pg_temp.bridge_outcome(8001)::text)$q$,'42501','POLAT_EXPERIMENT_UNAVAILABLE','old/wrong dispatch token cannot complete');
select is(pg_temp.bridge_record(8001)->>'stage','PROVIDER_RESULT','actual supplied fixture result is recorded');
select is(pg_temp.bridge_record(8001)->>'replay','true','identical outcome replay is idempotent');
select is((select stop_reason from private.polat_experiment_runs where id=pg_temp.bridge_id(8001,'2000')),'BILLING_UNVERIFIED','API success is not a verified bill');
select throws_ok($q$select pg_temp.bridge_reserve(8001,2)$q$,'55000','POLAT_EXPERIMENT_STOPPED','unknown billing blocks the next request');
select is(pg_temp.bridge_record(8001,1,'RECONCILIATION','SIMULATED_RECONCILED')->>'actual_billed_amount',null,'simulated reconciliation never creates actual billing');
select is((select request_count from private.polat_experiment_runs where id=pg_temp.bridge_id(8001,'2000')),1,'reconciliation never refunds request count');
select is((select reserved_liability from private.polat_experiment_runs where id=pg_temp.bridge_id(8001,'2000')),0.02::numeric,'reconciliation never resets reserved maximum');
select is((select stop_reason from private.polat_experiment_runs where id=pg_temp.bridge_id(8001,'2000')),'BILLING_UNVERIFIED','fixture reconciliation cannot activate genuine continuation');

select pg_temp.bridge_reserve(8002);select pg_temp.bridge_begin(8002);
select is(pg_temp.bridge_record(8002,1,'RESULT_UNKNOWN','UNKNOWN','NOT_EVALUATED')->>'stage','RESULT_UNKNOWN','unknown remote completion is an immutable fact');
select is(pg_temp.bridge_begin(8002)->>'dispatch','false','unknown completion cannot be blindly resent');
select is(pg_temp.bridge_record(8002)->>'stage','DELAYED_RESULT','late provider result appends instead of overwriting UNKNOWN');
select is((select count(*)from private.polat_experiment_evidence where run_id=pg_temp.bridge_id(8002,'2000')and stage='RESULT_UNKNOWN'),1::bigint,'original unknown record preserved');
select is(pg_temp.bridge_record(8002,1,'RECONCILIATION','INCOMPLETE')->>'stage','RECONCILIATION','failed/incomplete reconciliation remains evidence');
select is((select stop_reason from private.polat_experiment_runs where id=pg_temp.bridge_id(8002,'2000')),'UNKNOWN_REMOTE_COMPLETION','late observation cannot force successful recovery');
select pg_temp.bridge_reserve(8003);select pg_temp.bridge_begin(8003);select pg_sleep(.005);
select is(pg_temp.bridge_record(8003)->>'stage','DELAYED_RESULT','deadline expiry fences even a syntactically successful result');
select is((select count(*)from private.polat_experiment_evidence where run_id=pg_temp.bridge_id(8003,'2000')and stage='PROVIDER_RESULT'),0::bigint,'stale attempt cannot claim on-time success');
select pg_temp.bridge_reserve(8004);
select throws_ok($q$select pg_temp.bridge_reserve(8004,2)$q$,'54000','POLAT_EXPERIMENT_LIMIT','spend cap includes every reserved/failed/unknown request');
select is((select reserved_liability from private.polat_experiment_runs where id=pg_temp.bridge_id(8004,'2000')),0.02::numeric,'failed reservation cannot change counters');

-- Rollback covers reservation, counter and the native audit in the same SQL transaction.
do $$begin begin perform pg_temp.bridge_reserve(8005);raise exception 'CONTROLLED_ROLLBACK';exception when raise_exception then if sqlerrm<>'CONTROLLED_ROLLBACK'then raise;end if;end;end;$$;
select is((select request_count from private.polat_experiment_runs where id=pg_temp.bridge_id(8005,'2000')),0,'aborted reservation rolls back count');
select is((select count(*)from private.polat_experiment_attempts where run_id=pg_temp.bridge_id(8005,'2000')),0::bigint,'aborted reservation leaves no partial attempt');
select is((select count(*)from public.audit_logs where action='polat.experiment_reserved'and tenant_id=pg_temp.bridge_id(8005,'1000')),0::bigint,'aborted reservation leaves no audit claim');
select pg_temp.bridge_reserve(8005);select pg_temp.bridge_begin(8005);
select throws_ok($q$update private.polat_experiment_attempts set liability=0 where run_id=pg_temp.bridge_id(8005,'2000')$q$,'42501','FSE_IMMUTABLE','reservation append-only');
select throws_ok($q$delete from private.polat_experiment_evidence where run_id=pg_temp.bridge_id(8005,'2000')$q$,'42501','FSE_IMMUTABLE','outcome/history append-only');
select throws_ok($q$update private.polat_experiment_runs set request_count=0 where id=pg_temp.bridge_id(8005,'2000')$q$,'42501','POLAT_EXPERIMENT_IMMUTABLE','budget counter cannot be reset');
select throws_ok($q$update private.polat_experiment_runs set binding=jsonb_set(binding,'{model}','"other"')where id=pg_temp.bridge_id(8005,'2000')$q$,'42501','POLAT_EXPERIMENT_IMMUTABLE','model/binding immutable');
select throws_ok($q$select private.polat_experiment_record_fixture(pg_temp.bridge_id(8005,'1000'),pg_temp.bridge_id(8005,'2000'),pg_temp.bridge_id(800501,'3000'),(select binding_hash from private.polat_experiment_runs where id=pg_temp.bridge_id(8005,'2000')),pg_temp.bridge_id(800501,'4000'),(pg_temp.bridge_outcome(8005)||'{"prompt":"PRIVATE_SYNTHETIC_TEXT"}'::jsonb)::text)$q$,'22023','POLAT_EXPERIMENT_INVALID','no raw prompt in persisted result');
select throws_ok($q$select private.polat_experiment_record_fixture(pg_temp.bridge_id(8005,'1000'),pg_temp.bridge_id(8005,'2000'),pg_temp.bridge_id(800501,'3000'),(select binding_hash from private.polat_experiment_runs where id=pg_temp.bridge_id(8005,'2000')),pg_temp.bridge_id(800501,'4000'),jsonb_set(pg_temp.bridge_outcome(8005),'{actual_billed_amount}','"0.01"')::text)$q$,'22023','POLAT_EXPERIMENT_INVALID','fixture cannot manufacture genuine billed authority');
select ok(not exists(select 1 from private.polat_experiment_evidence where payload::text~'PRIVATE_SYNTHETIC_TEXT|x-api-key'),'evidence contains no rejected prompt or credential');

select is(jsonb_array_length(private.polat_experiment_read_fixture(pg_temp.bridge_id(8001,'1000'),pg_temp.bridge_id(8001,'2000'),0,1)->'items'),1,'bounded first page');
select is(private.polat_experiment_read_fixture(pg_temp.bridge_id(8001,'1000'),pg_temp.bridge_id(8001,'2000'),0,1)->>'has_more','true','lookahead honestly reports more');
select is(jsonb_array_length(private.polat_experiment_read_fixture(pg_temp.bridge_id(8001,'1000'),pg_temp.bridge_id(8001,'2000'),3,25)->'items'),0,'empty final page');
select is(private.polat_experiment_read_fixture(pg_temp.bridge_id(8001,'1000'),pg_temp.bridge_id(8001,'2000'),0,1,1)->>'has_newer','true','anchored page discloses later append');
select throws_ok($q$select private.polat_experiment_read_fixture(pg_temp.bridge_id(8001,'1000'),pg_temp.bridge_id(8001,'2000'),0,101)$q$,'22023','POLAT_EXPERIMENT_INVALID','hard server read cap100');
select throws_ok($q$select private.polat_experiment_read_fixture(pg_temp.bridge_id(8002,'1000'),pg_temp.bridge_id(8001,'2000'))$q$,'42501','POLAT_EXPERIMENT_UNAVAILABLE','no cross-tenant read/existence leak');
select pg_temp.bridge_reserve(8006);select pg_temp.bridge_begin(8006);select pg_temp.bridge_record(8006,1,'RESULT_UNKNOWN','UNKNOWN','NOT_EVALUATED');
do $$declare p jsonb;i integer;begin for i in 1..130 loop
 p:=jsonb_set(pg_temp.bridge_outcome(8006,1,'RECONCILIATION','INCOMPLETE'),'{evidence_id}',to_jsonb(pg_temp.bridge_id(900000+i,'5000')));
 perform private.polat_experiment_record_fixture(pg_temp.bridge_id(8006,'1000'),pg_temp.bridge_id(8006,'2000'),pg_temp.bridge_id(800601,'3000'),(select binding_hash from private.polat_experiment_runs where id=pg_temp.bridge_id(8006,'2000')),pg_temp.bridge_id(800601,'4000'),p::text);
end loop;end;$$;
select is(jsonb_array_length(private.polat_experiment_read_fixture(pg_temp.bridge_id(8006,'1000'),pg_temp.bridge_id(8006,'2000'))->'items'),25,'default page is25 even with132 historical records');
select is(jsonb_array_length(private.polat_experiment_read_fixture(pg_temp.bridge_id(8006,'1000'),pg_temp.bridge_id(8006,'2000'),0,100)->'items'),100,'hard max page100 bounded independently of history');
select is(jsonb_array_length(private.polat_experiment_read_fixture(pg_temp.bridge_id(8006,'1000'),pg_temp.bridge_id(8006,'2000'),100,100)->'items'),32,'secondary page retains all remaining evidence');
select is(private.polat_experiment_read_fixture(pg_temp.bridge_id(8006,'1000'),pg_temp.bridge_id(8006,'2000'),100,100)->>'has_more','false','final history page is complete');
select ok(not exists(select 1 from(select sequence,previous_hash,lag(evidence_hash)over(order by sequence)expected from private.polat_experiment_evidence where run_id=pg_temp.bridge_id(8006,'2000'))x where previous_hash is distinct from expected),'history chain is complete and append-only across pages');
select ok(not has_table_privilege('authenticated','private.polat_experiment_runs','select'),'authenticated cannot raw-read experiment identity');
select ok(not has_table_privilege('service_role','private.polat_experiment_evidence','insert'),'service role gains no writer');
select ok(not has_function_privilege('service_role','private.polat_experiment_prepare_fixture(uuid,uuid,text)','execute'),'service role cannot prepare a run');
select ok(not has_function_privilege('authenticated','private.polat_experiment_reserve_fixture(uuid,uuid,uuid,text,text,text,text)','execute'),'authenticated cannot reserve/dispatch');
select ok(not has_function_privilege('anon','private.polat_experiment_begin_fixture(uuid,uuid,uuid,text,uuid,uuid)','execute'),'anonymous cannot begin');
select ok((select bool_and(relrowsecurity)from pg_class where oid in('private.polat_experiment_runs'::regclass,'private.polat_experiment_attempts'::regclass,'private.polat_experiment_evidence'::regclass)),'RLS defense in depth on all private experiment tables');
select is((select count(*)from private.verified_payment_receipts where tenant_id in(select id from public.tenants where slug like 'polat-sandbox-experiment-%')),0::bigint,'no genuine receipt created');
select is((select count(*)from public.domain_events where tenant_id in(select id from public.tenants where slug like 'polat-sandbox-experiment-%')),0::bigint,'no payment/subscription event emitted');
select ok(not exists(select 1 from private.polat_experiment_runs where binding->>'financial_authority'<>'NONE'or binding->'authorized_external_requests'<>'0'::jsonb),'all persisted authority remains zero');
select * from finish();
rollback;
